INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p017:vehicle_identification','summary','en','VIN plate: RH inner wing valance; VIN also etched in lower LH corners of windscreen and rear window. Engine number is stamped on the front face of the cylinder block adjacent to the alternator; gearbox number is on the upper final-drive housing label; body number is on the bonnet locking platform.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
