INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p017:vin_decoding','summary','en','The VIN encodes geographic area, country, manufacturer, marque/model, class, body, engine, transmission/steering, model change, assembly plant and a six-figure serial number. Paint and trim use three-letter codes on the VIN plate.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
