INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p019:ignition_safety','summary','en','Inspect and insulate high-tension terminals, adapters and diagnostic equipment before ignition-system work. Pacemaker wearers must not remain close to ignition circuits or diagnostic equipment.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
