INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p019:used_oil_health','summary','en','Avoid prolonged or repeated used-oil skin contact; use protective clothing/gloves, wash thoroughly, obtain prompt first aid for wounds and use eye protection when splash risk exists.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
