INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p020:brake_hydraulics','summary','en','Use compatible brake fittings and two spanners on pipe/hose connections; keep hydraulic fluid and containers absolutely clean, never reuse system fluid, prevent mineral-oil contamination, cap disconnected unions and avoid kinked/chafing hose or pipe runs.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
