INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p021:threads_and_torque','title','en','Thread, joint and torque practice','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p021:threads_and_torque','summary','en','Fit joints dry unless specified otherwise; remove old jointing material without damaging faces; discard damaged fasteners; do not chase damaged threads with taps/dies as a substitute for replacement; keep oil/grease out of blind threaded holes; use specified torque. For a torque re-check, slacken a quarter turn then retighten to specification.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
