INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p024:fluoroelastomer_hazard','summary','en','Fluoroelastomer parts are normally safe, but fire or excessive heat can produce highly corrosive hydrofluoric acid. Avoid contact with burnt material and seek immediate medical assistance after exposure.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
