INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p025:fuel_tank_drain','title','en','Fuel-tank draining and removal','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p025:fuel_tank_drain','summary','en','Never drain/extract fuel while the vehicle is over a pit. Drain in a well-ventilated area into an adequately sized, clearly labelled approved receptacle; keep ignition precautions in force after draining. Release the spring steel clip before disconnecting the tank outlet line and label removed tanks for petrol-vapour hazard.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
