INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p026:body_heat_fuel_precaution','title','en','Fuel-line and tank precautions for body/chassis heat repair','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p026:body_heat_fuel_precaution','summary','en','Remove nearby fuel pipes and plug the tank outlet before applying heat; remove the tank when the repair is near it. Plastic fuel pipes are heat-sensitive. Do not remove fuel lines or tanks while the vehicle is over an inspection pit.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
