INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p027:electrical_testing','summary','en','Verify test equipment and harnesses before testing; observe polarity; use insulated tools on live high-tension circuits; keep connectors dry/oil-free, release locking tabs and never separate connectors by pulling the harness.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
