INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p032:workshop_jacking','summary','en','Front, side and rear jacking must use the numbered reinforced points defined on page 31; matching safety supports are required. Wheel-free lifts use the specified floor/sill or subframe longitudinal points and must be checked for secure support before full height.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
