INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p032:towing_general','summary','en','A recovery trailer or two-wheel ambulance is recommended. Use only the specified front/rear lashing points. For suspended towing release handbrake, select neutral and set ignition to position I. Do not use the car to tow another vehicle or trailer.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
