INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p033:towing_manual','summary','en','Tow from the front using the front lashing/towing eye, ignition key at position I to keep steering unlocked, gearbox in neutral and handbrake released. Do not tow with a gearbox/driveshaft fault or wheel/driveshaft contact with body/frame; braking effort increases with engine stopped.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
