INSERT INTO mems_doc_text(entity_key,field_key,locale,text_value,translation_status,translation_method,source_locale,notes) VALUES ('rcl0193eng:p033:towing_automatic','summary','en','Use suspended towing because the automatic gearbox is not adequately lubricated with the engine stopped. Selector must be N. Never use a rear suspended tow. An automatic model cannot be tow-started or push-started.','source','source_extraction','en',NULL) ON CONFLICT(entity_key,field_key,locale) DO UPDATE SET text_value=excluded.text_value,translation_status=excluded.translation_status,translation_method=excluded.translation_method,source_locale=excluded.source_locale,notes=excluded.notes;
